import * as React from 'react';
import { Button, Stack, Toast } from '@design-schema/rn';

function Demo(): React.JSX.Element {
  const [visible, setVisible] = React.useState(true);
  return (
    <Stack gap="loose" align="start">
      <Button label="Show toasts" onPress={() => setVisible(true)} />
      {visible ? (
        <Stack gap="tight" align="start">
          <Toast message="3 files deleted" actionLabel="Undo" duration="persistent" onDismiss={() => setVisible(false)} />
          <Toast message="Export ready" tone="success" actionLabel="View" duration="persistent" />
        </Stack>
      ) : null}
    </Stack>
  );
}

<Demo />
